const express = require('express');
const app = express();

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// POST handler for creating a new user with input validation
app.post('/users', express.json(), (req, res) => {
  const { name } = req.body;

  // Validate that name exists and is a string
  if (name === undefined) {
    return res.status(400).json({ error: 'Missing required field: name' });
  }

  if (typeof name !== 'string') {
    return res.status(400).json({ error: 'Name must be a string' });
  }

  // Additional validation: name should not be empty after trimming
  if (name.trim() === '') {
    return res.status(400).json({ error: 'Name cannot be empty' });
  }

  // If validation passes, create user (simplified for example)
  const newUser = {
    id: Date.now(), // Simple ID generation for demo
    name: name.trim(),
    email: `${name.toLowerCase().replace(/\s+/g, '.')}@example.com`
  };

  res.status(201).json(newUser);
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

